import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        if (!st.hasMoreTokens()) return;
        int n = Integer.parseInt(st.nextToken());

        String p = reader.readLine();
        while (p != null && p.trim().isEmpty()) {
            p = reader.readLine();
        }
        if (p == null) return;
        p = p.trim();

        int[] totalFreq = new int[26];
        for (int i = 0; i < n; i++) {
            totalFreq[p.charAt(i) - 'a']++;
        }

        List<Integer> divisors = new ArrayList<>();
        for (int i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                divisors.add(i);
                if (i * i != n) {
                    divisors.add(n / i);
                }
            }
        }
        Collections.sort(divisors);

        String answer = "*";

        int[] targetFreq = new int[26];
        int[] curFreq = new int[26];

        for (int l : divisors) {
            // Poligrama consiste na concatenação de duas ou mais palavras
            if (l >= n) {
                continue;
            }

            int k = n / l; // Número de blocos
            boolean possible = true;
            for (int c = 0; c < 26; c++) {
                if (totalFreq[c] % k != 0) {
                    possible = false;
                    break;
                }
            }
            if (!possible) {
                continue;
            }

            for (int c = 0; c < 26; c++) {
                targetFreq[c] = 0;
            }
            for (int i = 0; i < l; i++) {
                targetFreq[p.charAt(i) - 'a']++;
            }

            // O primeiro bloco deve conter exatamente totalFreq[c] / k de cada letra
            for (int c = 0; c < 26; c++) {
                if (targetFreq[c] != totalFreq[c] / k) {
                    possible = false;
                    break;
                }
            }
            if (!possible) {
                continue;
            }

            boolean allMatch = true;
            for (int b = 1; b < k; b++) {
                for (int c = 0; c < 26; c++) {
                    curFreq[c] = 0;
                }
                int offset = b * l;
                for (int i = 0; i < l; i++) {
                    curFreq[p.charAt(offset + i) - 'a']++;
                }
                for (int c = 0; c < 26; c++) {
                    if (curFreq[c] != targetFreq[c]) {
                        allMatch = false;
                        break;
                    }
                }
                if (!allMatch) {
                    break;
                }
            }

            if (allMatch) {
                answer = p.substring(0, l);
                break;
            }
        }

        System.out.println(answer);
    }
}
```

